-- Harbourview Marketplace industry-wide procurement catalogue v2
-- Reference/catalogue taxonomy only. No live supplier, stock, price, licence,
-- certification, availability, or regulatory approval is implied.
-- Idempotent by slug.

insert into public.listings (
  slug,title,description,marketplace_section,category,product_type,
  public_visibility,status,sold_by_harbourview,is_featured,
  high_level_specs,compliance_flags
)
select v.slug,v.title,v.description,v.section,v.category::marketplace_category,v.product_type,
       true,'approved',false,false,
       jsonb_build_object('catalogue',true,'review_required',true,'procurement_domain',v.domain),
       jsonb_build_object('review_required',true)
