('plc-control-system','PLC & Industrial Control System','Reference controls/automation category.','equipment','new_products','plc_controls','Automation'),
('machine-vision','Machine Vision Inspection System','Reference automated inspection category.','equipment','new_products','machine_vision','Automation'),
('scada-integration','SCADA & Controls Integration Service','Reference industrial controls integration service.','services','services','scada','Automation'),
