('office-computing','Business Computing Hardware','Reference corporate IT hardware category.','equipment','new_products','computing','Corporate'),
('networking-wifi','Business Networking & Wi-Fi Infrastructure','Reference network infrastructure category.','equipment','new_products','networking','IT'),
('endpoint-management','Endpoint Management & Device Services','Reference managed-device technology service category.','services','services','endpoint_management','IT'),
('erp-integration','ERP Implementation & Integration Service','Reference enterprise software implementation category.','services','services','erp','Software'),
('wms-integration','Warehouse Management System Integration','Reference WMS implementation/integration category.','services','services','wms','Software'),
